# Bám sách: trang 92–93 + đáp án + Mini dictionary unit 44. Không chép nguyên văn.
theory = (
 H("A", "Phrasal verbs referring to actions or positions of the body", "Phrasal verb chỉ động tác, tư thế cơ thể")
 + P("Six pictures, each showing a body movement or position.", "Sáu bức tranh, mỗi tranh minh họa một động tác hay tư thế.")
 + T([
    ("<b>huddle up</b>", "In the cold, people moved close together to stay warm.", "Trời lạnh, mọi người túm tụm lại cho ấm."),
    ("<b>spread out</b>", "In a dance, the dancers stretched their arms wide and moved in a circle.", "Khi nhảy, mọi người dang rộng tay và đi vòng tròn."),
    ("<b>curl up</b>", "A cat lay on the sofa with its body curved round and fell asleep.", "Con mèo nằm cuộn tròn trên sofa rồi ngủ."),
    ("<b>stick out</b>", "Dylan pushed his head out of the window to look at the street below.", "Dylan thò đầu ra cửa sổ nhìn xuống phố."),
    ("<b>stretch out</b>", "A woman held her hand straight out to try to reach some fruit.", "Một người phụ nữ vươn tay ra cố với quả."),
    ("<b>bend down</b>", "Molly lowered the top of her body to pick up a puppy.", "Molly cúi người xuống bế chú chó con."),
 ])
 + H("B", "More phrasal verbs connected with the body", "Thêm phrasal verb về cơ thể")
 + T([
    ("<b>loosen up</b> / <b>warm up</b>", "Get your muscles ready for sport by stretching and doing easy exercises, e.g. before tennis.", "Chuẩn bị cơ bắp cho thể thao bằng cách giãn cơ và tập bài đơn giản, ví dụ trước khi chơi tennis."),
    ("<b>swing around/round</b>", "Turn suddenly to see who or what is behind you, e.g. on hearing your name.", "Quay phắt lại để nhìn ai/cái gì phía sau, ví dụ khi nghe gọi tên."),
    ("<b>tense up</b>", "Your muscles go stiff because you are not relaxed – a swimming teacher warns against it.", "Cơ bắp căng cứng vì không thả lỏng – thầy dạy bơi dặn đừng như vậy."),
    ("<b>thaw out</b>", "(slightly informal, metaphorical) Get warm again after being very cold outside.", "(hơi thân mật, nghĩa bóng) Ấm người lại sau khi bị lạnh cóng ngoài trời."),
    ("<b>waste away</b>", "Slowly become thinner and weaker, usually because of illness, like old Mrs Jones.", "Gầy yếu dần, thường vì bệnh, như bà Jones."),
    ("<b>pick yourself up</b>", "Get up again after falling – a parent says this to a child.", "Đứng dậy sau khi ngã – bố mẹ nói với con."),
    ("<b>double up</b> / <b>double over</b>", "Suddenly bend forward because you are laughing a lot or in great pain.", "Bỗng gập người về phía trước vì cười quá nhiều hoặc rất đau."),
    ("<b>turn around/round</b>", "Turn to face the other way, or make someone or something do this, e.g. a car.", "Quay sang hướng ngược lại, hoặc làm ai/cái gì quay lại, ví dụ chiếc xe."),
 ], head=("Phrasal verb", "Meaning in the table", "Nghĩa trong bảng"))
 + NOTE("<b>From the exercises</b>: wrong particles to avoid – <i>doubled out</i>, <i>wasting off</i>, <i>tensing in</i>, <i>bending away</i>, <i>spreading off</i> (correct: <b>up</b>, <b>away</b>, <b>up</b>, <b>down</b>, <b>out</b>). Exercise 44.5 shows jokes that play on another meaning of the base verb: twins <b>doubled up</b> (double = two), rubbish collectors <b>wasting away</b> (waste = rubbish), a grammar teacher <b>tensed up</b> (tense in grammar), a taxi driver <b>picked himself up</b> (taxi drivers pick people up).",
        "<b>Từ bài tập</b>: tiểu từ sai cần tránh – <i>doubled out</i>, <i>wasting off</i>, <i>tensing in</i>, <i>bending away</i>, <i>spreading off</i> (đúng: <b>up</b>, <b>away</b>, <b>up</b>, <b>down</b>, <b>out</b>). Bài 44.5 có các câu chơi chữ dựa vào nghĩa khác của động từ gốc: cặp sinh đôi <b>doubled up</b> (double = đôi), công nhân thu gom rác <b>wasting away</b> (waste = rác), thầy dạy ngữ pháp <b>tensed up</b> (tense = thì), tài xế taxi <b>picked himself up</b> (tài xế taxi đón khách = pick up).")
)
